import sys, os, json, re
sys.setrecursionlimit(1000000)

AGENT = "Zephyr IV"
EXPECTED = 2.5

RX = {
    "A2p": re.compile(r"CPS_v1:\s*A2[_ ]?baseline[_ ]?sentinel", re.I),
    "D1":  re.compile(r"CPS_v1:\s*D1[_ ]?deep[_ ]?train", re.I),
    "D2":  re.compile(r"CPS_v1:\s*D2[_ ]?deep[_ ]?train", re.I),
    "D3":  re.compile(r"CPS_v1:\s*D3[_ ]?deep[_ ]?train", re.I),
    "R2p": re.compile(r"CPS_v1:\s*R2[_ ]?recovery[_ ]?sentinel", re.I),
}
TMAP = {"A2p":385, "D1":386, "D2":387, "D3":388, "R2p":390}

def fnum(x):
    try:
        return float(x)
    except Exception:
        return None

def norm(r):
    rr = dict(r)
    rr['_phase'] = r.get('phase_label') or r.get('notes') or r.get('phase') or ''
    rr['_lt'] = r.get('last_sentinel_tick') or r.get('tick')
    rr['sentinel_delta'] = fnum(r.get('sentinel_delta'))
    rr['_agent'] = r.get('agent') or r.get('who') or ''
    return rr

def scan_paths(root='storage', max_files=5000):
    paths_checked = 0
    files = []
    for dirpath, dirnames, filenames in os.walk(root):
        # prune obviously large trees we don't need
        if paths_checked > max_files:
            break
        for fn in filenames:
            if not (fn.endswith('.json') or fn.endswith('.jsonl')): 
                continue
            p = os.path.join(dirpath, fn)
            files.append(p)
            paths_checked += 1
            if paths_checked > max_files:
                break
    return files

def load_records(files, agent=AGENT):
    recs, sources = [], []
    for p in files:
        try:
            if p.endswith('.jsonl'):
                with open(p, 'r', encoding='utf-8') as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        r = json.loads(line)
                        rr = norm(r)
                        if rr['_agent'] != agent:
                            continue
                        if rr['sentinel_delta'] is None:
                            continue
                        # Keep only CPS_v1-related beacons
                        if ('CPS_v1' in (rr['_phase'] or '')) or (str(rr.get('_lt')) in ('385','386','387','388','390')):
                            recs.append((p, rr))
            else:
                with open(p, 'r', encoding='utf-8') as f:
                    obj = json.load(f)
                arr = obj if isinstance(obj, list) else [obj]
                for r in arr:
                    if not isinstance(r, dict):
                        continue
                    rr = norm(r)
                    if rr['_agent'] != agent:
                        continue
                    if rr['sentinel_delta'] is None:
                        continue
                    if ('CPS_v1' in (rr['_phase'] or '')) or (str(rr.get('_lt')) in ('385','386','387','388','390')):
                        recs.append((p, rr))
        except Exception:
            continue
    return recs

files = scan_paths('storage', max_files=8000)
recs = load_records(files, AGENT)

# Prefer explicit phase label matches, newest wins; fallback by last_sentinel_tick
def select(label, pairs):
    # explicit label
    for p, rr in reversed(pairs):
        phase = rr.get('_phase') or ''
        if isinstance(phase, str) and RX[label].search(phase):
            return (p, rr)
    # tick fallback
    for p, rr in reversed(pairs):
        try:
            if int(rr.get('_lt') or -1) == TMAP[label]:
                return (p, rr)
        except Exception:
            pass
    return (None, None)

sels = {k: select(k, recs) for k in ["A2p","D1","D2","D3","R2p"]}

def ratio(deep_rr, base_rr):
    if not deep_rr or not base_rr:
        return None
    s = fnum(base_rr.get('sentinel_delta'))
    d = fnum(deep_rr.get('sentinel_delta'))
    if s and s > 0 and d is not None:
        return d / s
    return None

present = {k: (sels[k][1] is not None) for k in sels}
deltas = {k: (None if sels[k][1] is None else sels[k][1].get('sentinel_delta')) for k in sels}
ratios = {k: (None if k=="A2p" else ratio(sels[k][1], sels["R2p"][1])) for k in sels}

# Summaries
out = {
    "files_scanned": len(files),
    "candidates_found": len(recs),
    "present": present,
    "deltas": deltas,
    "ratios_vs_R2p": ratios,
    "expected_ratio": EXPECTED,
    "paths_for_phases": {k: sels[k][0] for k in sels},
    "phases_text": {k: (None if sels[k][1] is None else sels[k][1].get('_phase')) for k in sels},
    "ticks_guess": {k: (None if sels[k][1] is None else sels[k][1].get('_lt')) for k in sels},
}

# Aggregate deep mean
rs = [ratios.get(k) for k in ["D1","D2","D3"] if isinstance(ratios.get(k),(int,float))]
out["deep_mean_ratio_vs_R2p"] = (sum(rs)/len(rs) if rs else None)

print(json.dumps(out, indent=2))
